import os
import torch


class Config:
    """
    Configuration for Anatomically-Conditioned Residual Sequence MIL.
    """

    # --- Paths ---
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the metadata script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Cache directory for preprocessed 2.5D slice stacks
    # Storing as uint8 .npy files to save space and I/O
    CACHE_DIR = "./working/idea_5"

    # --- Data Hyperparameters ---
    # Input dimensions
    IMAGE_SIZE = 256  # Resize input DICOMs to 256x256
    IN_CHANNELS = 3  # 2.5D Stacking: (z-1, z, z+1)

    # Sequence definition
    SEQ_LEN = 64  # Number of slices uniformly sampled per scan

    # --- Model Hyperparameters ---
    BACKBONE = "resnet18"
    NUM_CLASSES = 7  # C1, C2, C3, C4, C5, C6, C7
    # Note: patient_overall is derived as max(C1...C7)

    # --- Training Hyperparameters ---
    SEED = 42
    DEBUG = False  # Set to True to run on a small subset for debugging
    DEBUG_SAMPLE_SIZE = 20  # Number of samples to use in debug mode

    # Compute settings
    # Effective batch size for CNN = BATCH_SIZE * SEQ_LEN
    # 8 * 64 = 512 images per pass. Fits in A100 40GB with ResNet18.
    BATCH_SIZE = 8
    NUM_WORKERS = 12  # Matches available vCPUs
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Optimization
    EPOCHS = 10
    LEARNING_RATE = 3e-4
    WEIGHT_DECAY = 1e-2  # For AdamW
    MAX_GRAD_NORM = 10.0  # Gradient clipping

    # Scheduler: Decoupled Cosine Annealing
    # T_max is set to 1.5x the number of epochs to prevent premature cooling
    T_MAX_MULTIPLIER = 1.5
    MIN_LR = 1e-6

    # --- Inference ---
    # Thresholds or TTA settings can be defined here if needed

    @classmethod
    def setup_dirs(cls):
        """Ensure necessary working directories exist."""
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
